/*
 * A358193  Denominator of the quotient of the prime indices of the n-th
 *          semiprime.
 * https://oeis.org/A358193
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, frac
 * Formula:   a(n) = denominator of the reduced fraction of the prime indices
 *            of the n‑th semiprime
 * Range:     u8 none, u16 n <= 76, u32 n <= 76, u64 n <= 76, u128 n <= 76,
 *            big any n
 * Helpers:   build_primes_upto, gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by pre‑computing all semiprimes up to a
   fixed upper bound (10^7 in this implementation).  For each
   semiprime p_j · p_k (j ≤ k) the two indices j+1 and k+1 are
   reduced by their greatest common divisor; the denominator of
   the reduced quotient is returned.  The array of denominators is
   sorted according to the value of the semiprime, guaranteeing
   that a(1) corresponds to the smallest semiprime (4), a(2) to
   6, etc. */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>

#include "../utils/build_primes_upto.h"
#include "../utils/gcd.h"

/* Pair of semiprime value and its denominator. */
typedef struct {
    uint64_t value;   /* product of the two primes (semiprime) */
    seq_t   denom;    /* denominator of the reduced fraction of the indices */
} sempair_t;

/* Static storage for the precomputed sequence. */
static bool        initialized = false;
static sempair_t * pairs  = NULL;
static size_t      pair_count = 0;
static size_t      pair_cap   = 0;

/* Comparator for sorting semiprimes by their value. */
static int cmp_pair(const void *a, const void *b)
{
    const sempair_t *pa = (const sempair_t *)a;
    const sempair_t *pb = (const sempair_t *)b;
    if (pa->value < pb->value) return -1;
    if (pa->value > pb->value) return 1;
    return 0;
}

seq_t a(idx_t n)
{
    /* One‑time precomputation. */
    if (!initialized) {
        /* Upper bound for the semiprime values to generate.  */
        const uint64_t PRODUCT_LIMIT = 10000000ULL;   /* 10^7  */

        /* Upper bound for the primes needed: sqrt(PRODUCT_LIMIT). */
        const uint64_t PRIME_LIMIT = 4000ULL;         /* > sqrt(10^7) */

        /* Obtain the prime list. */
        uint64_t *primes = NULL;
        size_t    prime_cnt = 0;
        build_primes_upto(PRIME_LIMIT, &primes, &prime_cnt);

        /* Allocate an initial buffer for semiprimes. */
        pair_cap   = 20000;
        pair_count = 0;
        pairs = (sempair_t *)malloc(pair_cap * sizeof(sempair_t));

        /* Generate semiprimes (p_j * p_k  with j ≤ k) up to the limit. */
        for (size_t i = 0; i < prime_cnt; ++i) {
            uint64_t p = primes[i];
            for (size_t j = i; j < prime_cnt; ++j) {
                uint64_t q = primes[j];
                uint64_t prod = p * q;
                if (prod > PRODUCT_LIMIT) break;     /* inner loop terminates */

                /* Compute indices (1‑based). */
                seq_t idx1 = (seq_t)(i + 1);
                seq_t idx2 = (seq_t)(j + 1);

                /* Reduce the quotient idx1/idx2. */
                seq_t g     = gcd(idx1, idx2);
                seq_t denom = idx2 / g;              /* denominator of reduced fraction */

                /* Grow buffer if necessary. */
                if (pair_count == pair_cap) {
                    pair_cap *= 2;
                    pairs = (sempair_t *)realloc(pairs, pair_cap * sizeof(sempair_t));
                }

                pairs[pair_count].value = prod;
                pairs[pair_count].denom = denom;
                ++pair_count;
            }
        }

        /* Remember that primes are no longer needed. */
        free(primes);

        /* Sort semiprimes by value. */
        qsort(pairs, pair_count, sizeof(sempair_t), cmp_pair);

        initialized = true;
    }

    /* Return the denominator for the n‑th semiprime. */
    return pairs[(size_t)(n - 1)].denom;
}
